def solve(root):
    if isinstance(root, list):
        from collections import deque
        if not root: return []
        nodes = [None if v is None else [v, None, None] for v in root]
        parents = deque([nodes[0]]); i = 1
        while parents and i < len(nodes):
            parent = parents.popleft()
            for side in (1, 2):
                if i < len(nodes):
                    parent[side] = nodes[i]
                    if nodes[i] is not None: parents.append(nodes[i])
                    i += 1
        def visit(n): return None if n is None else (n[0], visit(n[1]), visit(n[2]))
        root = visit(nodes[0])
    elif root is not None:
        def visit(n): return None if n is None else (n.val, visit(n.left), visit(n.right))
        root = visit(root)
    if root is None: return []
    level = [root]; result = []
    while level:
        result.append(max(n[0] for n in level)-min(n[0] for n in level))
        level = [c for n in level for c in n[1:] if c is not None]
    return result
class Solution:
    def levelSpreads(self, root):
        return solve(root)
